import java.util.*;
import java.io.*;

public class Variant1 {
    static final long MOD = 998244353L;
    static long[] fac;
    static long[] invfac;

    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        long lmao = scanner.nextLong();
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            initializeFactorials();
            long result = power(C, N, MOD);
            for (int e = 1; e < C; e++) {
                long temp = power(C - e, N, MOD);
                temp = (temp * nCr(e, C)) % MOD;
                if (e % 2 == 1)
                    result = (result - temp + MOD) % MOD;
                else
                    result = (result + temp) % MOD;
            }
            result = (result * nCr(C, N)) % MOD;
            if (K > 0)
                result = (2 * result) % MOD;
            System.out.println(result);
        }
        scanner.close();
    }

    static void initializeFactorials() {
        fac = new long[200001];
        invfac = new long[200001];
        fac[0] = 1L;
        invfac[0] = 1L;
        for (int i = 1; i <= 200000; i++) {
            fac[i] = (fac[i - 1] * i) % MOD;
            invfac[i] = power(fac[i], MOD - 2, MOD);
        }
    }

    public static long nCr(int a, int b) {
        long res = fac[b];
        res = (res * invfac[a]) % MOD;
        res = (res * invfac[b - a]) % MOD;
        return res;
    }

    public static long power(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}
